static void pxafb_overlay_init ( struct pxafb_info * fbi ) { int i , ret ; if ( ! pxafb_overlay_supported ( ) ) { return ; } for ( i = 0 ; i < 2 ; i ++ ) { struct pxafb_layer * ofb = & fbi -> overlay [ i ] ; init_pxafb_overlay ( fbi , ofb , i ) ; ret = register_framebuffer ( & ofb -> fb ) ; if ( ret ) { dev_err ( fbi -> dev , "failed to register overlay %d\n" , i ) ; continue ; } ret = pxafb_overlay_map_video_memory ( fbi , ofb ) ; if ( ret ) { dev_err ( fbi -> dev , "failed to map video memory for overlay %d\n" , i ) ; unregister_framebuffer ( & ofb -> fb ) ; continue ; } } lcd_writel ( fbi , LCCR5 , ~ 0 ) ; pr_info ( "PXA Overlay driver loaded successfully!\n" ) ; } 